abstract class DeliveryNote{String trackingId;DeliveryNote(String i){trackingId=i;}abstract String confirmDelivery();String confirmDelivery(String signature){return confirmDelivery()+", signed by "+signature;}}class ParcelNote extends DeliveryNote{ParcelNote(String i){super(i);}String confirmDelivery(){return "Parcel "+trackingId+" delivered";}}class LetterNote extends DeliveryNote{LetterNote(String i){super(i);}String confirmDelivery(){return "Letter "+trackingId+" delivered";}}public class Main{static void logAll(DeliveryNote[] n){for(DeliveryNote x:n)System.out.println(x.confirmDelivery());}public static void main(String[]a){}}